// Typed access to the offline puzzle bank (generated by scripts/sudoku-bank.ts).
import bankJson from './bank.json';
import type { Difficulty } from './engine';
import type { Puzzle } from './session';

export interface BankPuzzle extends Puzzle {
  source: { generator: string; seed: number; minGivens: number };
  verification: { solutions: number; givensCount: number; logicSteps: number; techniques: Record<string, number> };
}
export const BANK = (bankJson as unknown as { puzzles: BankPuzzle[] }).puzzles;
export const bankFor = (d: Difficulty) => BANK.filter((p) => p.difficulty === d);

/** Picks a puzzle of the level, avoiding the most recently played ids (up to 10) when possible. */
export function pickPuzzle(d: Difficulty, recent: string[], rand = Math.random): BankPuzzle {
  const all = bankFor(d);
  const avoid = new Set(recent.slice(-10));
  const pool = all.filter((p) => !avoid.has(p.puzzleId));
  const from = pool.length ? pool : all;
  return from[Math.floor(rand() * from.length)];
}
